import{_ as t,o as i,c as o,a3 as a}from"./chunks/framework.vDgOMd_y.js";const m=JSON.parse('{"title":"Config overrides","description":"","frontmatter":{},"headers":[],"relativePath":"en/configuration/overrides.md","filePath":"en/configuration/overrides.md"}'),s={name:"en/configuration/overrides.md"};function n(r,e,l,d,c,p){return i(),o("div",null,[...e[0]||(e[0]=[a(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/configuration/overrides.md for this page in Markdown format</div><h1 id="config-overrides" tabindex="-1">Config overrides <a class="header-anchor" href="#config-overrides" aria-label="Permalink to &quot;Config overrides&quot;">​</a></h1><p>Kimi Code CLI has three places where runtime parameters can be influenced: the config file, command-line options, and environment variables. They are not a simple &quot;whoever has higher priority wins&quot; relationship — the three serve different scenarios and have non-overlapping scopes:</p><ul><li><strong>Config file</strong> stores long-term preferences (model, keys, loop control, etc.); takes effect on every startup</li><li><strong>Command-line options</strong> make one-off changes for the current startup; discarded after exit</li><li><strong>Environment variables</strong> primarily handle data directory location, OAuth endpoint switching, and a small number of runtime switches — <strong>not a general fallback mechanism for config fields</strong></li></ul><p>This distinction matters: many users run <code>export KIMI_API_KEY=xxx</code> in the shell expecting the CLI to pick it up automatically, but it does not. See <a href="#provider-credentials">Provider credentials</a> below for why.</p><h2 id="three-roles-of-environment-variables" tabindex="-1">Three roles of environment variables <a class="header-anchor" href="#three-roles-of-environment-variables" aria-label="Permalink to &quot;Three roles of environment variables&quot;">​</a></h2><p>Environment variables fall into three categories by function and cannot be collapsed into a single linear priority order:</p><ol><li><strong>Locating the config file</strong>: <code>KIMI_CODE_HOME</code> sets the data root directory, making the config file path <code>$KIMI_CODE_HOME/config.toml</code>. This step runs before all other resolution and is not a fallback for individual parameters.</li><li><strong>Runtime switches</strong>: A small set of variables like <code>KIMI_DISABLE_TELEMETRY</code> directly shut down the corresponding subsystem — even if <code>config.toml</code> has <code>telemetry = true</code>, setting this variable to a truthy value disables telemetry. The semantics are &quot;additionally disable&quot;, not &quot;ordinary override&quot;.</li><li><strong>Runtime endpoints and diagnostics</strong>: Variables like <code>KIMI_CODE_OAUTH_HOST</code>, <code>KIMI_CODE_BASE_URL</code>, and <code>KIMI_LOG_LEVEL</code> are read when the OAuth or logging subsystems initialize. For the full list, see <a href="./env-vars.html">Environment variables</a>.</li></ol><h2 id="priority-for-ordinary-runtime-parameters" tabindex="-1">Priority for ordinary runtime parameters <a class="header-anchor" href="#priority-for-ordinary-runtime-parameters" aria-label="Permalink to &quot;Priority for ordinary runtime parameters&quot;">​</a></h2><p>For ordinary runtime parameters such as model alias, Plan mode, yolo mode, and Skills directories, priority from highest to lowest is:</p><ol><li><strong>Command-line options</strong> (<code>-m</code>, <code>--plan</code>, <code>--yolo</code>, etc.): apply only to the current startup</li><li><strong>User config file</strong> (<code>~/.kimi-code/config.toml</code>): stores long-term preferences</li></ol><p>A small number of environment variables explicitly override specific config file fields — for example, <code>KIMI_CODE_BACKGROUND_KEEP_ALIVE_ON_EXIT</code> has higher priority than <code>[background].keep_alive_on_exit</code>. These exceptions are noted in <a href="./env-vars.html">Environment variables</a> and in the relevant field descriptions in <a href="./config-files.html">Configuration files</a>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Ordinary runtime parameters do not fall back to shell environment variables.</strong> Provider <code>api_key</code> / <code>base_url</code> are read only from <code>config.toml</code> (including the <code>[providers.&lt;name&gt;.env]</code> sub-table) and do not fall back to <code>export</code>-ed shell variables. The only exception is the explicit <code>KIMI_MODEL_*</code> channel — see <a href="./env-vars.html#define-a-model-from-environment-variables-kimi-model">Define a model from environment variables</a>.</p></div><p>The CLI currently reads a single user-level config file and has no project-level config file mechanism. To isolate config between different projects, point <code>KIMI_CODE_HOME</code> at different data directories — see <a href="#common-scenarios">Common scenarios</a> below.</p><h2 id="provider-credentials" tabindex="-1">Provider credentials <a class="header-anchor" href="#provider-credentials" aria-label="Permalink to &quot;Provider credentials&quot;">​</a></h2><p>Provider credentials (<code>api_key</code>, <code>base_url</code>) follow their own resolution rules, separate from the ordinary parameter priority chain.</p><p>For a single provider, credentials are resolved in this order:</p><ol><li><code>[providers.&lt;name&gt;].api_key</code> — key written directly in the config file; highest priority</li><li>The matching key inside the <code>[providers.&lt;name&gt;.env]</code> sub-table (<code>KIMI_API_KEY</code>, <code>ANTHROPIC_API_KEY</code>, etc.) — consulted only when <code>api_key</code> is empty</li><li>If both are absent — startup fails with an error indicating the provider is missing credentials</li></ol><p><code>base_url</code> is resolved the same way: first <code>[providers.&lt;name&gt;].base_url</code>, then the <code>*_BASE_URL</code> key in <code>[providers.&lt;name&gt;.env]</code>.</p><blockquote><p>The <code>[providers.&lt;name&gt;.env]</code> sub-table is just a TOML section in the config file — it does not write anything into the shell environment. It is only consulted when the corresponding direct field (<code>api_key</code> / <code>base_url</code>) is empty.</p></blockquote><p>For the full list of credential key names, see <a href="./env-vars.html#provider-credential-key-names-written-in-config-toml">Environment variables: provider credential key names</a>.</p><h2 id="command-line-options" tabindex="-1">Command-line options <a class="header-anchor" href="#command-line-options" aria-label="Permalink to &quot;Command-line options&quot;">​</a></h2><p>Options passed at startup have the highest priority and apply only to the current session:</p><table tabindex="0"><thead><tr><th>Option</th><th>Effect</th></tr></thead><tbody><tr><td><code>-S, --session [id]</code></td><td>Resume a specific session; enters interactive selection when no id is given</td></tr><tr><td><code>-c, --continue</code></td><td>Resume the last session for the current working directory</td></tr><tr><td><code>-y, --yolo</code></td><td>Auto-approve regular tool calls; the agent may still ask questions</td></tr><tr><td><code>--auto</code></td><td>Start in auto permission mode: fully autonomous, the agent will not ask questions</td></tr><tr><td><code>--plan</code></td><td>Start in Plan mode</td></tr><tr><td><code>-m, --model &lt;model&gt;</code></td><td>Use a specific model alias for this session</td></tr><tr><td><code>-p, --prompt &lt;prompt&gt;</code></td><td>Run in non-interactive mode: execute a single prompt and exit</td></tr><tr><td><code>--output-format &lt;format&gt;</code></td><td>Output format for <code>-p</code> mode: <code>text</code> or <code>stream-json</code></td></tr><tr><td><code>--skills-dir &lt;dir&gt;</code></td><td>Replace auto-discovered Skills directories (repeatable; applies to this session only)</td></tr></tbody></table><p>Mutual exclusion rules (startup fails if violated):</p><ul><li><code>--output-format</code> can only be used with <code>-p</code></li><li><code>--prompt</code> cannot be combined with <code>--yolo</code> or <code>--plan</code></li><li><code>--continue</code> and <code>--session</code> cannot be used together</li><li>In non-prompt mode, <code>--yolo</code> and <code>--plan</code> cannot be combined with <code>--continue</code> or <code>--session</code></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><code>--skills-dir</code> is a one-shot replacement that only affects the current startup. To persistently add search directories, write <code>extra_skill_dirs</code> in <code>config.toml</code> (see <a href="./../customization/skills.html">Agent Skills</a>).</p></div><h2 id="common-scenarios" tabindex="-1">Common scenarios <a class="header-anchor" href="#common-scenarios" aria-label="Permalink to &quot;Common scenarios&quot;">​</a></h2><p><strong>Isolated test environment</strong> — use a separate data directory to avoid polluting the main config and sessions:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KIMI_CODE_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.kimi-sandbox&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> kimi</span></span></code></pre></div><p><strong>One-off test key</strong> — since provider credentials are read only from the config file, write a test key into the <code>env</code> sub-table:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KIMI_API_KEY = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-test&quot;</span></span></code></pre></div><p><strong>Skip approval for batch tasks</strong>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yolo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Batch rename the following files...&quot;</span></span></code></pre></div><p><strong>Enter Plan mode temporarily</strong> (to make it permanent, set <code>default_plan_mode = true</code> in the config file):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --plan</span></span></code></pre></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./config-files.html">Configuration files</a> — complete reference for all configurable fields</li><li><a href="./env-vars.html">Environment variables</a> — full list and description of <code>KIMI_CODE_HOME</code> and related variables</li></ul>`,38)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
